WHERE label = 'A' AND question_id = (
    SELECT q.id FROM questions q
    JOIN subjects s ON s.id = q.subject_id
    WHERE s.name = 'PureMathematics U1' AND q.paper = 1 AND q.number = 32
      AND (2022 IS NULL OR q.year = 2022)
    LIMIT 1
);
